const listed = runGit(gitPath, ['config', '--list', '--show-scope', '-z']).trim().split('\0');
for (let i = 0; i + 1 < listed.length; i += 2) {
  const entry = listed[i + 1] as string;
  if (!SESSION_WRITABLE_SCOPES.includes(listed[i] as string)) continue;
  const key = entry.split('\n')[0] as string;
  // git-lfs reads plain `git config -l`, splitting lines on `\n` and keys on
  // the first `=`: a value line, or an `=` in a subsection, is a key to it.
  const lfsKeys = entry.replace('\n', '=').split('\n').map((line) => line.split('=')[0]);
  if ([key, ...lfsKeys].some((k) => k && ARMED_DRIVER_KEY.test(k))) armed.push(sanitizeReason(key));
}
